	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/admin/categories/{id}", wrapper.UpdateCategory)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/categories/{id}/move", wrapper.MoveCategory)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/items", wrapper.CreateItem)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/v1/admin/items/{id}", wrapper.DeleteItem)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/admin/items/{id}", wrapper.UpdateItem)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/items/{id}/move", wrapper.MoveItem)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/admin/modifier-groups", wrapper.CreateModifierGroup)
